    },
    {
      "name": "edge_save_device_parameters",
      "type": "edge_write",
      "description": "当前plan独立确认后保存网关20100024或回读XLBA参数；支持 node_key 或 node_keys 批量"
    },
    {
      "name": "edge_set_device_param",
      "type": "edge_write",
      "description": "批量/全量下发，不区分类型；模板会话按填报值、免模板直连会话逐台先读后端当前参数(20200002)，读不到则从设备档案(getDeviceList)组装 itemBody 后下发；仅 rtnCode=0 计成功"
    },
    {
      "name": "edge_call_clock",
      "type": "edge_write",
      "description": "独立确认召测网关时钟，无建档前置；不校时"
    },
    {
      "name": "edge_call_monitor_debug",
      "type": "edge_write",
      "description": "31800006监测点召测；rtnCode=0表示召测成功"
    },
    {
      "name": "execute_archive_task",
      "type": "edge_write",
      "description": "一键执行建档任务（完整/独立）；task_id 模式支持 stages 子集与 batch_size/budget 分批推进，返回续跑游标 cursor/remaining；独立模式对已存在网关执行时钟/下发/召测"
    },
    {
      "name": "get_device_archive_task_report",
      "type": "edge_read",
      "description": "按归属查询持久阶段报告，支持任务会话过期后查询"
    },
    {
      "name": "edge_check_monitor_online",
      "type": "edge_read",
      "description": "按设备类型判监测点在线（照明/配电房走感知事件，XLBA 走运维召测；模板与免模板直连/代理均支持，不阻塞）"
    },
    {
      "name": "edge_call_device_data",
      "type": "edge_write",
      "description": "旧召测兼容入口已阻断，不可替代31800006验收"
    },
    {
      "name": "edge_apply_compensation_plan",
      "type": "edge_write",
      "description": "按补偿清单确认式删除本次新建设备"
    },
    {
      "name": "edge_get_token",
      "type": "edge_util",
      "description": "独立登录边缘后端，返回 task_id 供后续 edge_* 工具使用"
    },
    {
      "name": "edge_delete_device",
      "type": "edge_write",
      "description": "删除设备（自动递归删除子设备，叶子优先）"
    },
    {
      "name": "validate_config_format",
      "type": "exec",
      "description": "校验转换配置 JSON 结构（MQTT/HTTP/Modbus 三契约，不执行）"
    },
    {
      "name": "generate_test_data",
      "type": "exec",
      "description": "生成 normal/boundary/abnormal 三组测试输入"
    },
    {
      "name": "execute_conversion_test",
      "type": "exec",
      "description": "沙箱执行转换测试并返回结构化报告（MQTT/HTTP）"
    },
    {
      "name": "get_test_report",
      "type": "exec",
      "description": "按 test_run_id 查询测试报告（归属校验）"
    },
    {
      "name": "save_conversion_config",
      "type": "exec",
      "description": "校验并保存转换配置 JSON（30 天 TTL）"
    },
    {
      "name": "pack_bundle",
      "type": "exec",
      "description": "打包配置+文档+测试报告为 ZIP（测试门控）"
    }
  ]
}

